import type {
  CastBy,
  Difference,
  Formality,
  Language,
  Loanword,
  Nuance,
  SentenceMedium,
  SentenceTone,
  SpeakerAge,
  SpeakerGender
} from "@kotori/domain"
import {
  bytea,
  doublePrecision,
  foreignKey,
  index,
  integer,
  jsonb,
  pgEnum,
  primaryKey,
  text,
  unique
} from "drizzle-orm/pg-core"
import { createdAt, table, timestamptz } from "./columns.ts"
import { entries, language, senses } from "./dictionary.ts"

// Everything here is generated by AI providers (Jev, Claude, ElevenLabs) for dictionary
// entries, keyed by entry and sense. It cascades from the dictionary and is rebuildable.

export const formality = pgEnum("formality", ["vulgar", "casual", "neutral", "polite", "formal"])
export const speakerGender = pgEnum("speaker_gender", ["masculine", "feminine", "unspecified"])
export const speakerAge = pgEnum("speaker_age", ["child", "youth", "adult", "middle-aged", "older", "unspecified"])
export const sentenceMedium = pgEnum("sentence_medium", ["conversation", "announcement", "narration"])
export const sentenceTone = pgEnum("sentence_tone", ["neutral", "cheerful", "serious", "gentle", "rough", "humorous"])
/** How a clip's voice was chosen; see docs/voice-casting.md. */
export const castBy = pgEnum("cast_by", ["rules", "jev", "manual"])
export const difference = pgEnum("difference", [
  "more_casual",
  "more_formal",
  "more_literary",
  "more_colloquial",
  "respectful",
  "humble",
  "more_specific",
  "more_general",
  "different_feeling",
  "different_usage"
])

/** Jev's nuance judgments per sense. */
export const senseNuance = table(
  "sense_nuance",
  {
    entryId: integer().notNull(),
    sense: integer().notNull(),
    nuance: jsonb().$type<Nuance>().notNull(),
    /** The raw answer distributions, so thresholds and labels can be re-derived without paying for inference again. */
    answers: jsonb().notNull(),
    model: text().notNull(),
    /** Which question set produced the answers (QUESTIONS_VERSION); old rows are refreshed on view. */
    questionsVersion: integer().notNull().default(1),
    createdAt: createdAt()
  },
  (t) => [
    primaryKey({ columns: [t.entryId, t.sense] }),
    foreignKey({ columns: [t.entryId, t.sense], foreignColumns: [senses.entryId, senses.position] }).onDelete("cascade")
  ]
)

/**
 * An English word's katakana loan, judged in the same Jev request as its senses: one row per
 * English entry the dictionary has katakana candidates for. Keeps the answers, so the verdict
 * can be re-derived, and Claude's warning, which survives a re-judge naming the same loan.
 */
export const loanWords = table("loan_words", {
  entryId: integer()
    .primaryKey()
    .references(() => entries.id, { onDelete: "cascade" }),
  /** The katakana loan, as JMDict spells it; null when Jev judged none of the candidates its loan. */
  word: text(),
  verdict: jsonb().$type<Loanword["verdict"]>(),
  /** Jev's answers about each candidate, and the candidates asked about. */
  answers: jsonb().notNull(),
  /** Claude's one-sentence warning, in Japanese, once the loan confidently diverges. */
  trap: text(),
  model: text().notNull(),
  /** Which question set produced the answers (QUESTIONS_VERSION). */
  questionsVersion: integer().notNull(),
  createdAt: createdAt()
})

export const similarWords = table(
  "similar_words",
  {
    entryId: integer().notNull(),
    sense: integer().notNull(),
    similarId: integer()
      .notNull()
      .references(() => entries.id, { onDelete: "cascade" }),
    similarity: doublePrecision().notNull(),
    difference: difference().$type<Difference>().notNull(),
    confidence: doublePrecision().notNull()
  },
  (t) => [
    primaryKey({ columns: [t.entryId, t.sense, t.similarId] }),
    foreignKey({ columns: [t.entryId, t.sense], foreignColumns: [senses.entryId, senses.position] }).onDelete("cascade")
  ]
)

/** Claude's usage note per sense, written alongside its example sentences. */
export const senseNotes = table(
  "sense_notes",
  {
    entryId: integer().notNull(),
    sense: integer().notNull(),
    /** On a Japanese word, for learners of Japanese, in English; null when the glosses say it all. */
    note: text(),
    /** On an English word, for learners of English, in Japanese; null likewise. */
    noteJa: text(),
    model: text().notNull(),
    createdAt: createdAt()
  },
  (t) => [
    primaryKey({ columns: [t.entryId, t.sense] }),
    foreignKey({ columns: [t.entryId, t.sense], foreignColumns: [senses.entryId, senses.position] }).onDelete("cascade")
  ]
)

export const examples = table(
  "examples",
  {
    id: integer().primaryKey().generatedAlwaysAsIdentity(),
    entryId: integer().notNull(),
    sense: integer().notNull(),
    position: integer().notNull(),
    ja: text().notNull(),
    /** The Japanese sentence with `{base|reading}` furigana. */
    furigana: text().notNull(),
    en: text().notNull(),
    formality: formality().$type<Formality>().notNull(),
    note: text(),
    /** The usage note for Japanese speakers learning English, in Japanese; null on sentences written before it. */
    noteJa: text(),
    // Casting signals, judged by the writer; null on sentences written before voice casting.
    speakerGender: speakerGender().$type<SpeakerGender>(),
    speakerAge: speakerAge().$type<SpeakerAge>(),
    medium: sentenceMedium().$type<SentenceMedium>(),
    /** Regional variety label such as "kansai" or "british"; null for the language's default. */
    variety: text(),
    tone: sentenceTone().$type<SentenceTone>(),
    model: text().notNull(),
    createdAt: createdAt()
  },
  (t) => [
    foreignKey({ columns: [t.entryId, t.sense], foreignColumns: [senses.entryId, senses.position] }).onDelete(
      "cascade"
    ),
    index("examples_sense").on(t.entryId, t.sense, t.position)
  ]
)

/**
 * Content-addressed speech clips: `key` is sha256(voice, model, text), so the same
 * phrase is never synthesised twice. Metadata here, bytes in `audio_files`.
 */
export const audio = table("audio", {
  key: text().primaryKey(),
  text: text().notNull(),
  language: language().$type<Language>().notNull(),
  /** The provider's voice id, part of the key. */
  voiceId: text().notNull(),
  /** The Kotori cast voice ("ja-kyoko"); null for clips made before casting or with an uncast provider voice. */
  voice: text(),
  modelId: text().notNull(),
  /** Characters billed by the provider, for the monthly budget. */
  characters: integer().notNull(),
  bytes: integer().notNull(),
  createdAt: createdAt()
})

/** The clip bytes, in the database so the API and the worker share them without a disk. */
export const audioFiles = table("audio_files", {
  key: text()
    .primaryKey()
    .references(() => audio.key, { onDelete: "cascade" }),
  data: bytea().notNull()
})

/** The pronunciations of an entry's headword, one clip per dictionary voice. */
export const entryAudio = table(
  "entry_audio",
  {
    entryId: integer()
      .notNull()
      .references(() => entries.id, { onDelete: "cascade" }),
    audioKey: text()
      .notNull()
      .references(() => audio.key)
  },
  (t) => [primaryKey({ columns: [t.entryId, t.audioKey] })]
)

/** An example sentence spoken, in Japanese and optionally in English. */
export const exampleAudio = table(
  "example_audio",
  {
    exampleId: integer()
      .notNull()
      .references(() => examples.id, { onDelete: "cascade" }),
    language: language().$type<Language>().notNull(),
    audioKey: text()
      .notNull()
      .references(() => audio.key),
    /** How the voice was chosen, and its casting score, for debugging and `kotori audio regen --dry-run`. */
    castBy: castBy().$type<CastBy>(),
    score: doublePrecision()
  },
  (t) => [primaryKey({ columns: [t.exampleId, t.language] })]
)

export const jobKind = pgEnum("job_kind", ["nuance", "examples", "audio"])
export const jobStatus = pgEnum("job_status", ["queued", "running", "done", "failed"])

/** Enrichment work queue, shared by the API (on-demand requests) and the worker. One job per kind and entry. */
export const jobs = table(
  "jobs",
  {
    id: integer().primaryKey().generatedAlwaysAsIdentity(),
    kind: jobKind().notNull(),
    entryId: integer()
      .notNull()
      .references(() => entries.id, { onDelete: "cascade" }),
    priority: integer().notNull().default(0),
    status: jobStatus().notNull().default("queued"),
    attempts: integer().notNull().default(0),
    error: text(),
    /** Not before this moment; pushed into the future by retries. */
    runAfter: timestamptz().notNull().defaultNow(),
    createdAt: createdAt(),
    updatedAt: timestamptz().notNull().defaultNow()
  },
  (t) => [
    unique("jobs_kind_entry").on(t.kind, t.entryId),
    index("jobs_pending").on(t.status, t.priority.desc(), t.runAfter)
  ]
)
